window.RP_SESSION={"id":"S-79669d3d0695","messages":[{"id":"RP-II-0065292","time":"2026-03-18T18:31:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"' 까드득... 까드득... '\n\n 마구간 앞에 놓인 나무 의자에 앉아 작은 목재블록을 정성스레 깎고 있는 스텔리온, 혹시나 모양이 망가지진 않을까 아주 신중하게 손을 움직이네요.","characters":["P-77eda225c108"]},{"id":"RP-II-0065293","time":"2026-03-18T19:08:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":" 그가 깎고 있던 목재블록은 점점 형태를 잡더니, 어느새 사람과 비슷한 모양이 됐네요.\n\n 결과물이 꽤 만족스러웠는지, 그 조각품을 이리저리 돌려봅니다.\n\n\" 음, 잘 만들었어. \"","characters":["P-77eda225c108"]},{"id":"RP-II-0065294","time":"2026-03-18T19:44:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"저 키 큰 사람은 왜 항상 혼자서 저러고 있을까? 델타인은 청소하며 신기하게 쳐다보았다.","characters":["P-c93f55c91873"]},{"id":"RP-II-0065295","time":"2026-03-18T19:48:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이봐요, 거기. 엉덩이 좀 치우세요. 저 청소해야해요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065296","time":"2026-03-18T19:51:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 뭐야? \"\n\n 그 명령에 본인도 모르게 살짝 비켜주네요.","characters":["P-77eda225c108"]},{"id":"RP-II-0065297","time":"2026-03-18T19:52:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"감사합니다.\"\n\n델타인은 촉수와 함께 나뭇잎이나 흘러온 먼지, 지푸라기 등을 싹싹 밀기 시작했다.","characters":["P-c93f55c91873"]},{"id":"RP-II-0065298","time":"2026-03-18T19:52:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"근데 왜 맨날 혼자 앉아계세요? 친구는요?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065299","time":"2026-03-18T19:53:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 친구ㅡ? 없다. 이 길드에 들어오긴 했지만.. 아직 친구 하나 없는 외톨이지. \"","characters":["P-77eda225c108"]},{"id":"RP-II-0065300","time":"2026-03-18T19:53:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 진짜요? 다른 엘프들에 비해 엘프치고 나이도 그리 적지 않은 편 같으신데….\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065301","time":"2026-03-18T19:53:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 넌 친구가 많이 있느냐? \"","characters":["P-77eda225c108"]},{"id":"RP-II-0065302","time":"2026-03-18T19:53:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"에휴, 전 9명이나 있죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065303","time":"2026-03-18T19:54:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"부모님이 아시면 기분이 어떠시겠어요? 맨날 앉아있지만 마시고 일이든 친구든 좀 구해보세요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065304","time":"2026-03-18T19:54:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"전 부모님이 없어서 하고 싶은대로 살거든요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065305","time":"2026-03-18T19:54:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 우리 부모님은 꽤 오래전에 가셨는데? \"","characters":["P-77eda225c108"]},{"id":"RP-II-0065306","time":"2026-03-18T19:54:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 내가 이제 우리 부모님보다 늙었단다. \"","characters":["P-77eda225c108"]},{"id":"RP-II-0065307","time":"2026-03-18T19:55:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"와, 역시! 당신도 고아군요? 하긴 어떤 부모님이 피부에 퍼런 칠 하고 다니는 걸 가만 냅두시겠어요.\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065308","time":"2026-03-18T19:55:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"우리 고아끼리 친구할까요? 제가 친구 해드릴게요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065309","time":"2026-03-18T19:56:00+09:00","room":"RP II","name":"스텔리온","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 그래, 친구! 역시 고아끼리는 통하는 게 있나 보구나. \"","characters":["P-77eda225c108"]},{"id":"RP-II-0065310","time":"2026-03-18T19:56:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 온갖 청소로 더러워진 손을 내밀었다.\n\n\"친구의 친구는 친구란 말 아시죠?\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065311","time":"2026-03-18T19:56:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이제 퍼랭이 씨는 친구가 10명이에요!\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065312","time":"2026-03-18T19:56:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델뻔뻔.","characters":["P-c93f55c91873"]},{"id":"RP-II-0065313","time":"2026-03-18T19:59:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"잠시만요, 제 친구 목록이 어디 있냐면….\"\n\n델타인이 소매 속을 뒤적거리더니 아주 낡은 양피지를 꺼냈다. 거기에는 여러 이름이 쓰여 있다. 딘, 폴라리스, 케닌, 미샤, 토르번, 니콜라스, 션, 피에르, 페디안.","characters":["P-c93f55c91873"]},{"id":"RP-II-0065314","time":"2026-03-18T20:19:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어때요? 고아 클럽도 들어오세요. 고아 클럽은 사람 수가 꽤 되거든요. 사실 길드에 고아 특별 전형이 있는 걸지도….\"","characters":["P-c93f55c91873"]},{"id":"RP-II-0065315","time":"2026-03-18T21:20:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-II-0065316","time":"2026-03-18T21:20:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
